import { describe, expect, it } from "vitest";
import { roundCents } from "../src/billing/round";

describe("roundCents", () => {
  it("rounds non-tie amounts to the nearest cent", () => {
    expect(roundCents(12.3)).toBe(12);
    expect(roundCents(12.7)).toBe(13);
  });

  it("sends exact halves to the even cent so ties don't bias invoices upward", () => {
    expect(roundCents(12.5)).toBe(12);
    expect(roundCents(13.5)).toBe(14);
    expect(roundCents(0.5)).toBe(0);
  });

  it("applies the same half-even rule to credits and refunds", () => {
    expect(roundCents(-12.5)).toBe(-12);
    expect(roundCents(-13.5)).toBe(-14);
    expect(roundCents(-12.7)).toBe(-13);
  });

  it("leaves whole cents unchanged", () => {
    expect(roundCents(42)).toBe(42);
  });
});

